mod common;
use serde_json::Value;
use openvector::region_data::Raster;
use openvector::subpixel::*;
fn bytes(v:&Value)->Vec<u8>{v.as_array().unwrap().iter().map(|v|v.as_u64().unwrap() as u8).collect()}
fn ints(v:&Value)->Vec<i64>{v.as_array().unwrap().iter().map(|v|v.as_i64().unwrap()).collect()}
fn floats(v:&Value)->Vec<f64>{v.as_array().unwrap().iter().map(|v|v.as_f64().unwrap()).collect()}
fn neighborhood(v:&Value)->Neighborhood{match v.as_str().unwrap(){"eight"=>Neighborhood::Eight,"twenty-four"=>Neighborhood::TwentyFour,_=>panic!("invalid fixture neighborhood")}}
fn model(f:&Value)->SubpixelModel{SubpixelModel::new(f["width"].as_i64().unwrap(),f["height"].as_i64().unwrap(),&bytes(&f["bgra"]),&ints(&f["regions"]),&f["parameters"],neighborhood(&f["neighborhood"])).unwrap()}
fn assert_state(actual:&SubpixelState,e:&Value,label:&str){
    assert_eq!(actual.indices.iter().map(|&v|v as i64).collect::<Vec<_>>(),ints(&e["indices"]),"{label} indices");assert_eq!(actual.costs.iter().map(|&v|v as f64).collect::<Vec<_>>(),floats(&e["costs"]),"{label} costs");
    let expected=e["regions"].as_array().unwrap();assert_eq!(actual.regions.len(),expected.len(),"{label} region count");
    for(i,(s,e))in actual.regions.iter().zip(expected).enumerate(){assert_eq!(s.count as u64,e["count"].as_u64().unwrap(),"{label}/{i} count");assert_eq!(s.interior_count as u64,e["interiorCount"].as_u64().unwrap(),"{label}/{i} interior count");assert_eq!(s.color_index as i64,e["colorIndex"].as_i64().unwrap(),"{label}/{i} color index");for(key,values)in [("sums",&s.sums),("squares",&s.squares),("color",&s.color),("interiorSums",&s.interior_sums),("interiorSquares",&s.interior_squares)]{assert_eq!(values.iter().map(|&v|v as f64).collect::<Vec<_>>(),floats(&e[key]),"{label}/{i} {key}");}assert_eq!(s.boundary.iter().map(|&v|v as i64).collect::<Vec<_>>(),ints(&e["boundary"]),"{label}/{i} boundary");assert_eq!(s.interior_error,e["interiorError"].as_f64().unwrap(),"{label}/{i} interior error");assert_eq!(s.error,e["error"].as_f64().unwrap(),"{label}/{i} error");}
}
fn merge(model:&mut SubpixelModel,m:&Value){model.merge(m["source"].as_u64().unwrap() as usize,m["target"].as_u64().unwrap() as usize).unwrap();}
fn proposal(model:&mut SubpixelModel,p:&Value)->f64{model.merge_cost(p["source"].as_u64().unwrap() as usize,p["target"].as_u64().unwrap() as usize,p["lambda"].as_f64().unwrap()).unwrap()}
#[test]
fn all_540_native_subpixel_statistic_snapshots(){let data=common::read_json("subpixel-statistics-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),540);for(i,f)in cases.iter().enumerate(){let state=build_subpixel_statistics(f["width"].as_i64().unwrap(),f["height"].as_i64().unwrap(),&bytes(&f["bgra"]),&ints(&f["regions"]),&f["parameters"],neighborhood(&f["neighborhood"])).unwrap();assert_state(&state,&f["expected"],&format!("statistics {i}"));}}
#[test]
fn all_native_directed_merge_queries(){let data=common::read_json("subpixel-merge-cost-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),540);let(mut bounded,mut complete)=(0,0);for(i,f)in cases.iter().enumerate(){let mut model=model(f);let before=model.snapshot();for(q,p)in f["queries"].as_array().unwrap().iter().enumerate(){assert_eq!(proposal(&mut model,p),p["expected"]["cost"].as_f64().unwrap(),"query {i}/{q}");if p["expected"]["lowerBound"].as_f64().unwrap()>p["lambda"].as_f64().unwrap() as f32 as f64{bounded+=1;}else{complete+=1;}}assert_eq!(model.snapshot(),before);}assert!(bounded>0&&complete>0);}
#[test]
fn all_340_native_incremental_merge_sequences(){let data=common::read_json("subpixel-merge-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),340);for(i,f)in cases.iter().enumerate(){let mut model=model(f);for(step,m)in f["merges"].as_array().unwrap().iter().enumerate(){merge(&mut model,m);assert_eq!(proposal(&mut model,&m["proposal"]),m["proposal"]["expected"].as_f64().unwrap(),"merge proposal {i}/{step}");assert_state(&model.snapshot(),&m["expected"],&format!("merge {i}/{step}"));}}}
#[test]
fn all_540_native_ordered_pass_sequences(){let data=common::read_json("subpixel-pass-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),540);let mut changing=0;for(i,f)in cases.iter().enumerate(){let mut model=model(f);for(step,p)in f["passes"].as_array().unwrap().iter().enumerate(){let merges=model.iterate(p["lambda"].as_f64().unwrap(),p["maximumSourcePixels"].as_i64().unwrap(),p["maximumTargetPixels"].as_i64().unwrap(),p["sourceCount"]=="interior").unwrap();assert_eq!(merges,p["expectedMerges"].as_u64().unwrap() as usize,"pass merges {i}/{step}");assert_state(&model.snapshot(),&p["expected"],&format!("pass {i}/{step}"));changing+=usize::from(merges>0);}}assert!(changing>0);}
#[test]
fn all_540_native_rebuilds_preserve_cache_and_neighborhood(){let data=common::read_json("subpixel-rebuild-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),540);let mut thin=0;for(i,f)in cases.iter().enumerate(){let mut model=model(f);for m in f["merges"].as_array().unwrap(){merge(&mut model,m);}let before=model.snapshot();assert_state(&before,&f["beforeCleanup"],&format!("rebuild before {i}"));assert_state(&before,&f["afterCleanup"],&format!("thin cleanup {i}"));for(region,s)in before.regions.iter().enumerate(){if s.count>0&&s.interior_count==0{thin+=1;assert!(s.boundary.iter().any(|&p|before.indices[p]!=region as i32));}}for(step,r)in f["rebuilds"].as_array().unwrap().iter().enumerate(){model.rebuild(neighborhood(&r["neighborhood"])).unwrap();assert_state(&model.snapshot(),&r["expected"],&format!("rebuild {i}/{step}"));}}assert!(thin>0);}
#[test]
fn all_432_native_complete_schedules(){let data=common::read_json("subpixel-optimization-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),432);for(i,f)in cases.iter().enumerate(){let pixels=bytes(&f["bgra"]);let labels=ints(&f["regions"]).into_iter().map(|v|v as i32).collect::<Vec<_>>();let raster=Raster{width:f["width"].as_u64().unwrap() as usize,height:f["height"].as_u64().unwrap() as usize,bgra:&pixels};assert_state(&optimize_subpixel(raster,&labels,&f["parameters"],None).unwrap(),&f["expected"],&format!("schedule {i}"));}}
#[test]
fn all_1644_native_palette_projections_and_retained_assignments(){let data=common::read_json("subpixel-palette-projection-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),1644);for(i,f)in cases.iter().enumerate(){let mut model=model(f);assert_state(&model.snapshot(),&f["before"],&format!("projection before {i}"));model.project_palette(&floats(&f["palette"]),f["minimumInteriorPixels"].as_i64().unwrap()).unwrap();assert_state(&model.snapshot(),&f["expected"],&format!("projection {i}"));model.project_palette(&[1.0,0.0,1.0,1.0],f["minimumInteriorPixels"].as_i64().unwrap()).unwrap();assert_state(&model.snapshot(),&f["expected"],&format!("retained {i}"));}}
#[test]
fn all_7832_native_boundary_evaluations_and_548_color_selections(){let data=common::read_json("subpixel-color-selection-reference.json");let cases=data["cases"].as_array().unwrap();assert_eq!(cases.len(),548);let(mut queries,mut changed,mut capped)=(0,0,0);for(i,f)in cases.iter().enumerate(){let mut model=model(f);let before=model.snapshot();assert_state(&before,&f["before"],&format!("color before {i}"));for(q,p)in f["queries"].as_array().unwrap().iter().enumerate(){assert_eq!(model.boundary_cost(p["source"].as_u64().unwrap() as usize,p["target"].as_u64().unwrap() as usize,p["budget"].as_f64().unwrap()).unwrap(),p["expected"].as_f64().unwrap(),"boundary {i}/{q}");queries+=1;}assert_eq!(model.snapshot(),before);model.select_colors(f["margin"].as_f64().unwrap()).unwrap();let after=model.snapshot();assert_state(&after,&f["expected"],&format!("color selected {i}"));changed+=after.regions.iter().zip(&before.regions).filter(|(a,b)|a.color!=b.color).count();capped+=usize::from(before.regions.iter().filter(|s|s.interior_count>=3).count()>100);}assert_eq!(queries,7832);assert!(changed>0&&capped>0);}
#[test]
fn invalid_controls_and_snapshots_do_not_mutate_models(){let data=common::read_json("subpixel-merge-reference.json");let f=&data["cases"][0];let mut model=model(f);let before=model.snapshot();assert!(model.merge(0,0).is_err());assert!(model.merge(0,before.regions.len()).is_err());assert!(model.merge_cost(0,0,f64::INFINITY).is_err());assert!(model.boundary_cost(0,0,-1.0).is_err());assert!(model.select_colors(-1.0).is_err());assert!(model.project_palette(&[],0).is_err());assert!(model.iterate(1.0,-1,10,false).is_err());assert_eq!(model.snapshot(),before);let mut copy=model.snapshot();copy.indices.fill(7);copy.costs.fill(7.0);assert_eq!(model.snapshot(),before);let m=&f["merges"][0];merge(&mut model,m);let after=model.snapshot();assert!(model.merge(m["source"].as_u64().unwrap() as usize,m["target"].as_u64().unwrap() as usize).is_err());assert_eq!(model.snapshot(),after);}

fn read_state(value:&Value)->SubpixelState{
    let array=|v:&Value|-> [f32;4]{floats(v).into_iter().map(|v|v as f32).collect::<Vec<_>>().try_into().unwrap()};
    SubpixelState{indices:ints(&value["indices"]).into_iter().map(|v|v as i32).collect(),costs:floats(&value["costs"]).into_iter().map(|v|v as f32).collect(),regions:value["regions"].as_array().unwrap().iter().map(|s|SubpixelRegion{count:s["count"].as_u64().unwrap() as u32,sums:array(&s["sums"]),color_index:s["colorIndex"].as_i64().unwrap() as i32,squares:array(&s["squares"]),interior_count:s["interiorCount"].as_u64().unwrap() as u32,interior_sums:array(&s["interiorSums"]),interior_squares:array(&s["interiorSquares"]),color:array(&s["color"]),boundary:ints(&s["boundary"]).into_iter().map(|v|v as usize).collect(),interior_error:s["interiorError"].as_f64().unwrap(),error:s["error"].as_f64().unwrap()}).collect()}
}
fn feature_bits(values:&[f64])->Value{Value::Array(values.iter().map(|v|Value::String(v.to_le_bytes().iter().map(|b|format!("{b:02x}")).collect())).collect())}
#[test]
fn all_646_native_shadow_refinements_and_feature_bits(){
    let rows=common::read_ndjson("shadow-refinement-reference.ndjson.gz");let(mut explicit,mut images,mut shadows,mut empty,mut maximum,mut accepted,mut rejected,mut mixed)=(0,0,0,0,0,0,0,0);
    for f in &rows{
        if f["type"]=="metadata"{for key in ["wholeNativeResponseRepeatIdentical","wholeHardwareTraceRepeatIdentical","originalResultPayloadIdentical"]{assert_eq!(f[key],true);}continue;}
        if f["type"]=="summary"{continue;}assert_eq!(f["type"],"case");
        let pixels=bytes(&f["bgra"]);let raster=Raster{width:f["width"].as_u64().unwrap() as usize,height:f["height"].as_u64().unwrap() as usize,bgra:&pixels};
        let before=read_state(&f["before"]);let features:Vec<[f64;42]>=f["features"].as_array().unwrap().iter().map(|v|floats(v).try_into().unwrap()).collect();let flags=bytes(&f["shadowFlags"]);
        let refined=refine_shadow_state(raster,&before,&features,&flags,&f["parameters"],f["control"].as_i64().unwrap() as i32).unwrap();assert_state(&before,&f["before"],"input preserved");
        let label=f["id"].as_str().unwrap();if !f["trace"].as_array().unwrap().is_empty(){assert_state(refined.before.as_ref().unwrap(),&f["trace"][1]["state"],label);assert_state(refined.after.as_ref().unwrap(),&f["trace"][3]["state"],label);}
        if f["context"]=="explicit"{
            assert_state(&refined.state,&f["expected"],label);let bits=Value::Array(refined.features.iter().map(|v|feature_bits(v)).collect());assert_eq!(bits,f["expectedFeatureBits"],"{label} all feature bits");assert_eq!(refined.accepted,bytes(&f["expectedAccepted"]),"{label} accepted");
            let count=flags.iter().filter(|&&v|v&1!=0).count();let kept=refined.accepted.iter().filter(|&&v|v!=0).count();shadows+=count;empty+=usize::from(count==0);maximum=maximum.max(count);accepted+=kept;rejected+=count-kept;mixed+=usize::from(kept>0&&kept<count);explicit+=1;
        }else{
            assert_eq!(f["context"],"image");assert_eq!(refined.state.indices.iter().map(|&v|v as i64).collect::<Vec<_>>(),ints(&f["expectedIndices"]),"{label} final labels");
            let region=f["region"].as_u64().unwrap() as usize;assert_eq!(feature_bits(&refined.features[region]),f["expectedFeatureBits"][0],"{label} acceptance vector");assert_eq!(refined.accepted[region]!=0,f["accepted"].as_bool().unwrap());images+=1;
        }
    }
    assert_eq!((explicit,images,shadows,empty,maximum,accepted,rejected,mixed),(640,6,7600,160,86,7576,24,24));
}
